 await assert.rejects(f.session.draftKey({resource:{type:'hifz-journal',studentId:'synthetic'},draftGeneration:1,originalExpiresAtMs:f.session.getState().originalExpiresAtMs,context:f.session.getContext()}),{code:'AUTH_TRANSPORT_UNAVAILABLE'});
 assert.equal(f.requests.filter(x=>x.path==='/auth/v2/draft-key').length,1);assert.equal(lease.claims,0);f.session.dispose();
