 await assert.rejects(f.session.refresh(),{code:'COORDINATION_LOST'});assert.equal(lease.claims,1);assert.equal(lease.releases,1);assert.equal(f.session.getState().masked,true);assert.equal(f.requests.filter(x=>x.path==='/auth/v2/status').length,1);f.session.dispose();
