 f.setHook(c=>c.path==='/api/wrong'?new Response('{}',{headers:{'X-UAA-Contract':'2','X-UAA-Context':b64({...current,sv:current.sv+1}),'X-UAA-Server-Now-Ms':String(f.now)}}):undefined);
