test('same-tab S256 callback binds independent state/verifier, fixed finalize operation, context and body-only code',async()=>{
 const f=fixture();f.context=null;f.state='SIGNED_OUT';const tx=crypto.randomUUID(),finalizeId=crypto.randomUUID();let start;
 f.setHook(c=>{if(c.path==='/auth/v2/admission/start'){start=c;return json(f.dto('admission/start',{tx,operationId:finalizeId,expiresAtMs:f.now+300000,navigateUrl:ACADEMY+'/auth/v2/admission/continue?tx='+tx}));}if(c.path==='/auth/v2/bootstrap'&&c.body.purpose==='admission/finalize')return json(f.dto('admission/finalize',{intent:{id:finalizeId,kind:'admission/finalize',generation:1,expiresAtMs:f.now+60000}}));if(c.path==='/auth/v2/admission/finalize'){f.context=selector();f.state='ADMITTED_LOCKED';return json(f.dto('admission/finalize',{operationId:finalizeId,returnTo:'/journal'}));}});
 const begin=await f.session.beginAdmission({returnTo:'/journal'});assert.equal(begin.operationId,finalizeId);const entry=JSON.parse(f.storage.getItem('uaa-ceremony-v2:'+tx));assert.notEqual(entry.state,entry.verifier);assert.equal(entry.state.length,43);assert.equal(entry.verifier.length,43);assert.equal(start.body.challenge,Buffer.from(await crypto.subtle.digest('SHA-256',Buffer.from(entry.verifier))).toString('base64url'));assert(!start.url.includes(entry.verifier));assert.equal(start.body.state,undefined);assert.equal(start.body.stateHash,Buffer.from(await crypto.subtle.digest('SHA-256',Buffer.from(entry.state))).toString('hex'));assert(!JSON.stringify(start.body).includes(entry.state));
 const count=f.requests.length;await assert.rejects(f.session.completeCallback({tx,state:entry.state,code:'synthetic-code'}),{code:'INVALID_CEREMONY_CALLBACK'});await assert.rejects(f.session.completeCallback({tx,stateHash:'0'.repeat(64),code:'synthetic-code'}),{code:'CEREMONY_STATE_MISMATCH'});assert.equal(f.requests.length,count);
 const done=await f.session.completeCallback({tx,stateHash:start.body.stateHash,code:'synthetic-code'});assert.equal(done.returnTo,ORIGIN+'/journal');assert.equal(f.storage.getItem('uaa-ceremony-v2:'+tx),null);const call=f.requests.find(x=>x.path==='/auth/v2/admission/finalize');assert.equal(call.body.operationId,finalizeId);assert.equal(call.body.code,'synthetic-code');assert.equal(call.body.verifier,entry.verifier);assert(!call.url.includes('synthetic-code'));f.session.dispose();
});

